// VS Screen
const VSScreen = ({ team1, team2, trainer1, trainer2, onComplete }) => {
  useEffect(() => { const timer = setTimeout(onComplete, 2500); return () => clearTimeout(timer); }, [onComplete]);
  return (
    <div style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'linear-gradient(135deg, #1a1a2e 0%, #16213e 100%)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 2000 }}>
      <style>{`
        @keyframes slideInLeft { from { transform: translateX(-100vw); } to { transform: translateX(0); } }
        @keyframes slideInRight { from { transform: translateX(100vw); } to { transform: translateX(0); } }
        @keyframes vsGrow { 0% { transform: scale(0) rotate(-180deg); } 50% { transform: scale(1.3) rotate(10deg); } 100% { transform: scale(1) rotate(0deg); } }
        @keyframes vsPulse { 0%, 100% { text-shadow: 0 0 15px #FFD700; } 50% { text-shadow: 0 0 30px #FFD700, 0 0 50px #FFD700; } }
      `}</style>
      <div style={{ display: 'flex', alignItems: 'center', gap: '40px' }}>
        <div style={{ animation: 'slideInLeft 0.5s ease-out', textAlign: 'center' }}>
          {trainer1 && <img src={trainer1.img} alt={trainer1.name} style={{ width: '50px', height: '50px', marginBottom: '5px', imageRendering: 'pixelated' }} />}
          <div style={{ color: trainer1?.color, fontWeight: 'bold', fontSize: '18px', marginBottom: '8px' }}>{trainer1?.name}</div>
          <div style={{ display: 'flex', gap: '8px' }}>
            {team1.map((p, i) => <img key={i} src={p.img} alt={p.name} style={{ width: '80px', height: '80px', filter: `drop-shadow(0 0 10px ${trainer1?.color})` }} />)}
          </div>
        </div>
        <div style={{ fontSize: '70px', fontWeight: 'bold', color: '#FFD700', animation: 'vsGrow 0.6s ease-out 0.3s both, vsPulse 1s ease-in-out 0.9s infinite' }}>VS</div>
        <div style={{ animation: 'slideInRight 0.5s ease-out', textAlign: 'center' }}>
          {trainer2 && <img src={trainer2.img} alt={trainer2.name} style={{ width: '50px', height: '50px', marginBottom: '5px', imageRendering: 'pixelated' }} />}
          <div style={{ color: trainer2?.color, fontWeight: 'bold', fontSize: '18px', marginBottom: '8px' }}>{trainer2?.name}</div>
          <div style={{ display: 'flex', gap: '8px' }}>
            {team2.map((p, i) => <img key={i} src={p.img} alt={p.name} style={{ width: '80px', height: '80px', filter: `drop-shadow(0 0 10px ${trainer2?.color})` }} />)}
          </div>
        </div>
      </div>
    </div>
  );
};;

const FloatingText = ({ text, color, large, x }) => (
  <div style={{ position: 'absolute', left: x || '50%', top: '35%', transform: 'translate(-50%, -50%)', fontSize: large ? '40px' : '28px', fontWeight: 'bold', color: color || 'white', textShadow: `0 0 12px ${color || 'white'}, 0 0 24px ${color || 'white'}, 2px 2px 0 #000`, animation: 'floatUp 1.2s ease-out forwards', zIndex: 1000, pointerEvents: 'none', whiteSpace: 'nowrap' }}>
    <style>{`@keyframes floatUp { 0% { opacity: 1; transform: translate(-50%, -50%) scale(0.5); } 20% { transform: translate(-50%, -50%) scale(1.2); } 40% { transform: translate(-50%, -60%) scale(1); } 100% { opacity: 0; transform: translate(-50%, -120%) scale(0.8); } }`}</style>
    {text}
  </div>
);

const ScreenFlash = ({ color }) => (
  <div style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: color, animation: 'flash 0.3s ease-out forwards', pointerEvents: 'none', zIndex: 999 }}>
    <style>{`@keyframes flash { 0% { opacity: 0.7; } 100% { opacity: 0; } }`}</style>
  </div>
);

const HealthBar = ({ current, max }) => {
  const pct = Math.max(0, (current / max) * 100);
  const barColor = pct > 50 ? '#4CAF50' : pct > 20 ? '#FFC107' : '#E53935';
  return (
    <div style={{ width: '100%', height: '12px', backgroundColor: '#1a1a2e', borderRadius: '6px', overflow: 'hidden', border: '1px solid #333' }}>
      <div style={{ width: `${pct}%`, height: '100%', background: barColor, borderRadius: '5px', transition: 'width 0.5s ease-out' }} />
    </div>
  );
};

const PokemonCard = ({ pokemon, selected, onClick, disabled }) => {
  const typeData = TYPE_DATA[pokemon.type];
  return (
    <div onClick={disabled ? null : onClick} style={{ padding: '4px', borderRadius: '10px', background: selected ? typeData.bg : 'linear-gradient(145deg, #2d2d44, #1a1a2e)', border: selected ? '3px solid #FFD700' : '2px solid #444', cursor: disabled ? 'not-allowed' : 'pointer', opacity: disabled ? 0.3 : 1, textAlign: 'center', transition: 'all 0.2s', transform: selected ? 'scale(1.05)' : 'scale(1)', boxShadow: selected ? '0 0 12px rgba(255,215,0,0.6)' : 'none' }}>
      <img src={pokemon.img} alt={pokemon.name} style={{ width: '56px', height: '56px' }} />
      <div style={{ fontWeight: 'bold', fontSize: '9px', color: 'white', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{pokemon.name}</div>
      <div style={{ fontSize: '10px' }}>{typeData.icon}</div>
    </div>
  );
};

const BattlePokemon = ({ pokemon, hp, maxHp, status, statBoosts, shaking, flashing, fainting, isActive }) => {
  const typeData = TYPE_DATA[pokemon.type];
  const statusInfo = status ? STATUS_DATA[status] : null;
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', animation: shaking ? 'shake 0.4s ease-in-out' : fainting ? 'faint 0.8s ease-out forwards' : 'none' }}>
      <style>{`
        @keyframes shake { 0%, 100% { transform: translateX(0); } 20% { transform: translateX(-10px); } 40% { transform: translateX(10px); } 60% { transform: translateX(-6px); } 80% { transform: translateX(6px); } }
        @keyframes faint { 0% { transform: translateY(0) rotate(0); opacity: 1; } 100% { transform: translateY(50px) rotate(15deg); opacity: 0; } }
        @keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-5px); } }
      `}</style>
      {statusInfo && <div style={{ padding: '2px 6px', borderRadius: '5px', backgroundColor: statusInfo.color, color: 'white', fontSize: '9px', fontWeight: 'bold', marginBottom: '2px' }}>{statusInfo.icon} {statusInfo.name}</div>}
      {statBoosts && (statBoosts.atk > 0 || statBoosts.def > 0 || statBoosts.spd > 0) && (
        <div style={{ display: 'flex', gap: '2px', marginBottom: '2px' }}>
          {statBoosts.atk > 0 && <span style={{ background: '#E53935', padding: '1px 3px', borderRadius: '3px', color: 'white', fontSize: '8px', fontWeight: 'bold' }}>+{statBoosts.atk}ATK</span>}
          {statBoosts.def > 0 && <span style={{ background: '#2196F3', padding: '1px 3px', borderRadius: '3px', color: 'white', fontSize: '8px', fontWeight: 'bold' }}>+{statBoosts.def}DEF</span>}
          {statBoosts.spd > 0 && <span style={{ background: '#4CAF50', padding: '1px 3px', borderRadius: '3px', color: 'white', fontSize: '8px', fontWeight: 'bold' }}>+{statBoosts.spd}SPD</span>}
        </div>
      )}
      <img
        src={pokemon.img}
        alt={pokemon.name}
        style={{
          width: 'min(35vh, 180px)',
          height: 'min(35vh, 180px)',
          objectFit: 'contain',
          imageRendering: 'pixelated',
          animation: 'float 2s ease-in-out infinite',
          filter: flashing ? 'brightness(3)' : isActive ? 'drop-shadow(0 0 8px #FFD700)' : 'drop-shadow(0 2px 4px rgba(0,0,0,0.3))',
          transition: 'filter 0.1s'
        }}
      />
      <div style={{ marginTop: '2px', padding: '4px 8px', background: 'linear-gradient(180deg, #2d2d44 0%, #1a1a2e 100%)', borderRadius: '6px', minWidth: 'min(100px, 15vw)', border: `2px solid ${isActive ? '#FFD700' : typeData.color}`, boxShadow: isActive ? '0 0 10px #FFD700' : 'none' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '3px', marginBottom: '3px' }}>
          <span style={{ fontSize: '12px' }}>{typeData.icon}</span>
          <span style={{ fontSize: '10px', fontWeight: 'bold', color: 'white' }}>{pokemon.name}</span>
        </div>
        <HealthBar current={hp} max={maxHp} />
        <div style={{ fontSize: '9px', color: '#aaa', marginTop: '2px', textAlign: 'center', fontFamily: 'monospace' }}>{hp}/{maxHp}</div>
      </div>
    </div>
  );
};

const AttackButton = ({ attack, onClick, disabled, defenderType, slotIndex }) => {
  const slotColors = [
    { bg: 'linear-gradient(135deg, #E53935 0%, #C62828 100%)', border: '#EF5350' },
    { bg: 'linear-gradient(135deg, #1E88E5 0%, #1565C0 100%)', border: '#42A5F5' },
    { bg: 'linear-gradient(135deg, #43A047 0%, #2E7D32 100%)', border: '#66BB6A' },
    { bg: 'linear-gradient(135deg, #FB8C00 0%, #EF6C00 100%)', border: '#FFA726' },
  ];
  const slot = slotColors[slotIndex % 4];

  return (
    <button onClick={onClick} disabled={disabled} style={{ padding: '10px 12px', fontSize: '12px', fontWeight: 'bold', background: disabled ? '#444' : slot.bg, color: 'white', border: `2px solid ${disabled ? '#555' : slot.border}`, borderRadius: '6px', cursor: disabled ? 'not-allowed' : 'pointer', boxShadow: disabled ? 'none' : '0 2px 5px rgba(0,0,0,0.3)', textShadow: '1px 1px 1px rgba(0,0,0,0.5)', minWidth: '115px', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
      {attack.name}
    </button>
  );
};

const AttackAnimation = ({ type, side }) => {
  const typeData = TYPE_DATA[type] || TYPE_DATA.normal;
  return (
    <div style={{ position: 'absolute', top: '10%', left: side === 'left' ? '55%' : '10%', width: '35%', height: '80%', pointerEvents: 'none', zIndex: 100 }}>
      <style>{`@keyframes attackBurst { 0% { transform: scale(0) rotate(0deg); opacity: 1; } 50% { opacity: 1; } 100% { transform: scale(3) rotate(180deg); opacity: 0; } }`}</style>
      {Array(12).fill(0).map((_, i) => (
        <div key={i} style={{ position: 'absolute', left: `${10 + Math.random() * 80}%`, top: `${5 + Math.random() * 90}%`, fontSize: '45px', animation: `attackBurst 0.6s ease-out ${i * 0.025}s forwards`, filter: `drop-shadow(0 0 8px ${typeData.color})` }}>{typeData.icon}</div>
      ))}
    </div>
  );
};

const TeamIndicator = ({ team, hpArray, activeIndex, statuses, onSwitch, canSwitch }) => (
  <div style={{ display: 'flex', gap: '4px', justifyContent: 'center', marginBottom: '4px' }}>
    {team.map((p, i) => {
      const typeData = TYPE_DATA[p.type];
      const status = statuses?.[i];
      const isClickable = canSwitch && hpArray[i] > 0 && i !== activeIndex;
      return (
        <div key={i} onClick={isClickable ? () => onSwitch(i) : null} style={{ width: '40px', height: '40px', borderRadius: '50%', background: i === activeIndex ? '#FFD700' : hpArray[i] > 0 ? typeData.color : '#444', display: 'flex', alignItems: 'center', justifyContent: 'center', boxShadow: i === activeIndex ? '0 0 8px #FFD700' : 'none', opacity: hpArray[i] > 0 ? 1 : 0.4, border: i === activeIndex ? '2px solid white' : '1px solid #333', position: 'relative', cursor: isClickable ? 'pointer' : 'default', overflow: 'hidden' }}>
          <img src={p.img} alt={p.name} style={{ width: '36px', height: '36px' }} />
          {status && <div style={{ position: 'absolute', bottom: -2, right: -2, fontSize: '8px', background: STATUS_DATA[status].color, borderRadius: '50%', width: '12px', height: '12px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{STATUS_DATA[status].icon}</div>}
          {isClickable && <div style={{ position: 'absolute', top: -3, right: -3, fontSize: '8px', background: '#4CAF50', borderRadius: '50%', width: '12px', height: '12px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontWeight: 'bold' }}>↺</div>}
        </div>
      );
    })}
  </div>
);

export default function PokemonBattle() {
  const [phase, setPhase] = useState('trainer1');
  const [trainer1, setTrainer1] = useState(null);
  const [trainer2, setTrainer2] = useState(null);
  const [player1Team, setPlayer1Team] = useState([]);
  const [player2Team, setPlayer2Team] = useState([]);
  const [player1Active, setPlayer1Active] = useState(0);
  const [player2Active, setPlayer2Active] = useState(0);
  const [player1HP, setPlayer1HP] = useState([]);
  const [player2HP, setPlayer2HP] = useState([]);
  const [player1Status, setPlayer1Status] = useState([null, null, null]);
  const [player2Status, setPlayer2Status] = useState([null, null, null]);
  const [player1Boosts, setPlayer1Boosts] = useState([{atk:0,def:0,spd:0},{atk:0,def:0,spd:0},{atk:0,def:0,spd:0}]);
  const [player2Boosts, setPlayer2Boosts] = useState([{atk:0,def:0,spd:0},{atk:0,def:0,spd:0},{atk:0,def:0,spd:0}]);
  const [player1SleepTurns, setPlayer1SleepTurns] = useState([0,0,0]);
  const [player2SleepTurns, setPlayer2SleepTurns] = useState([0,0,0]);
  const [turn, setTurn] = useState(1);
  const [message, setMessage] = useState('');
  const [winner, setWinner] = useState(null);
  const [animating, setAnimating] = useState(false);
  const [shakeTarget, setShakeTarget] = useState(null);
  const [flashTarget, setFlashTarget] = useState(null);
  const [faintingPokemon, setFaintingPokemon] = useState(null);
  const [attackAnim, setAttackAnim] = useState(null);
  const [floatingTexts, setFloatingTexts] = useState([]);
  const [screenFlash, setScreenFlash] = useState(null);
  const [showVS, setShowVS] = useState(false);
  const [showConfetti, setShowConfetti] = useState(false);
  
  const { playSound, playAttackSound, playPokemonCry } = useSound();

  const addFloatingText = (text, color, large = false, side = null) => {
    const id = Date.now() + Math.random();
    const x = side === 'left' ? '25%' : side === 'right' ? '75%' : '50%';
    setFloatingTexts(prev => [...prev, { id, text, color, large, x }]);
    setTimeout(() => setFloatingTexts(prev => prev.filter(t => t.id !== id)), 1200);
  };

  const resetGame = () => {
    setPhase('trainer1'); setTrainer1(null); setTrainer2(null);
    setPlayer1Team([]); setPlayer2Team([]); setPlayer1Active(0); setPlayer2Active(0);
    setPlayer1HP([]); setPlayer2HP([]); setPlayer1Status([null,null,null]); setPlayer2Status([null,null,null]);
    setPlayer1Boosts([{atk:0,def:0,spd:0},{atk:0,def:0,spd:0},{atk:0,def:0,spd:0}]);
    setPlayer2Boosts([{atk:0,def:0,spd:0},{atk:0,def:0,spd:0},{atk:0,def:0,spd:0}]);
    setPlayer1SleepTurns([0,0,0]); setPlayer2SleepTurns([0,0,0]);
    setTurn(1); setMessage(''); setWinner(null); setAnimating(false); setFloatingTexts([]);
    setShowVS(false); setShowConfetti(false);
  };

  const selectPokemon = (pokemon, player) => {
    playSound('select');
    const team = player === 1 ? player1Team : player2Team;
    const setTeam = player === 1 ? setPlayer1Team : setPlayer2Team;
    if (team.find(p => p.id === pokemon.id)) setTeam(team.filter(p => p.id !== pokemon.id));
    else if (team.length < 3) setTeam([...team, pokemon]);
  };

  const startBattle = () => { playSound('vs'); setShowVS(true); };
  const onVSComplete = () => { setShowVS(false); setPlayer1HP(player1Team.map(p => p.hp)); setPlayer2HP(player2Team.map(p => p.hp)); setPhase('battle'); setMessage(`Battle Start! ${trainer1.name}'s turn!`); };

  const handleSwitch = (newIndex) => {
    if (animating) return;
    setAnimating(true);
    const isP1 = turn === 1;
    const team = isP1 ? player1Team : player2Team;
    const setActive = isP1 ? setPlayer1Active : setPlayer2Active;
    const nextTrainer = isP1 ? trainer2 : trainer1;
    setMessage(`${team[newIndex].name}, go!`);
    setActive(newIndex);
    setTimeout(() => { setTurn(turn === 1 ? 2 : 1); setMessage(`${nextTrainer.name}'s turn!`); setAnimating(false); }, 800);
  };

  const doAttack = (attack) => {
    if (animating) return;
    setAnimating(true);

    const isP1 = turn === 1;
    const attacker = isP1 ? player1Team[player1Active] : player2Team[player2Active];
    const defender = isP1 ? player2Team[player2Active] : player1Team[player1Active];
    const attackerStatus = isP1 ? player1Status[player1Active] : player2Status[player2Active];
    const attackerBoosts = isP1 ? player1Boosts[player1Active] : player2Boosts[player2Active];
    const defenderBoosts = isP1 ? player2Boosts[player2Active] : player1Boosts[player1Active];
    const defenderHP = isP1 ? [...player2HP] : [...player1HP];
    const setDefenderHP = isP1 ? setPlayer2HP : setPlayer1HP;
    const defenderActive = isP1 ? player2Active : player1Active;
    const setDefenderActive = isP1 ? setPlayer2Active : setPlayer1Active;
    const defenderTeam = isP1 ? player2Team : player1Team;
    const defenderStatusArr = isP1 ? [...player2Status] : [...player1Status];
    const setDefenderStatus = isP1 ? setPlayer2Status : setPlayer1Status;
    const attackerHP = isP1 ? [...player1HP] : [...player2HP];
    const setAttackerHP = isP1 ? setPlayer1HP : setPlayer2HP;
    const attackerActive = isP1 ? player1Active : player2Active;
    const attackerBoostsArr = isP1 ? [...player1Boosts] : [...player2Boosts];
    const setAttackerBoosts = isP1 ? setPlayer1Boosts : setPlayer2Boosts;
    const sleepTurns = isP1 ? [...player1SleepTurns] : [...player2SleepTurns];
    const setSleepTurns = isP1 ? setPlayer1SleepTurns : setPlayer2SleepTurns;
    const attackerStatusArr = isP1 ? [...player1Status] : [...player2Status];
    const setAttackerStatus = isP1 ? setPlayer1Status : setPlayer2Status;
    const attackerSide = isP1 ? 'left' : 'right';
    const defenderSide = isP1 ? 'right' : 'left';

    // Status checks
    if (attackerStatus === 'sleep') {
      sleepTurns[attackerActive]++;
      setSleepTurns(sleepTurns);
      if (sleepTurns[attackerActive] >= 2 + Math.floor(Math.random() * 2)) {
        attackerStatusArr[attackerActive] = null; setAttackerStatus(attackerStatusArr);
        setMessage(`${attacker.name} woke up!`); addFloatingText('AWAKE!', '#4CAF50', true, attackerSide);
      } else {
        setMessage(`${attacker.name} is asleep!`); addFloatingText('💤 ZZZ', '#3B9AE1', true, attackerSide);
        setTimeout(() => { setTurn(turn === 1 ? 2 : 1); setMessage(`${turn === 1 ? trainer2.name : trainer1.name}'s turn!`); setAnimating(false); }, 1200);
        return;
      }
    }
    
    if (attackerStatus === 'frozen') {
      if (Math.random() < 0.2) { attackerStatusArr[attackerActive] = null; setAttackerStatus(attackerStatusArr); setMessage(`${attacker.name} thawed!`); addFloatingText('THAWED!', '#51C4D3', true, attackerSide); }
      else { setMessage(`${attacker.name} is frozen!`); addFloatingText('🧊 FROZEN', '#51C4D3', true, attackerSide); setTimeout(() => { setTurn(turn === 1 ? 2 : 1); setMessage(`${turn === 1 ? trainer2.name : trainer1.name}'s turn!`); setAnimating(false); }, 1200); return; }
    }
    
    if (attackerStatus === 'paralysis' && Math.random() < 0.25) {
      setMessage(`${attacker.name} is paralyzed!`); addFloatingText("CAN'T MOVE!", '#FFD93D', true, attackerSide);
      setTimeout(() => { setTurn(turn === 1 ? 2 : 1); setMessage(`${turn === 1 ? trainer2.name : trainer1.name}'s turn!`); setAnimating(false); }, 1200);
      return;
    }

    setMessage(`${attacker.name} used ${attack.name}!`);
    
    // Play attack sound based on type!
    playAttackSound(attack.type);
    
    setAttackAnim({ type: attack.type, side: attackerSide });
    setTimeout(() => setAttackAnim(null), 600);

    setTimeout(() => {
      // Healing
      if (attack.heal || attack.fullHeal) {
        const healAmount = attack.fullHeal ? attacker.hp : Math.floor(attacker.hp * (attack.heal / 100));
        const actualHeal = Math.min(healAmount, attacker.hp - attackerHP[attackerActive]);
        attackerHP[attackerActive] = Math.min(attacker.hp, attackerHP[attackerActive] + healAmount);
        setAttackerHP(attackerHP);
        playSound('heal');
        addFloatingText(`+${actualHeal}`, '#4CAF50', true, attackerSide);
        setScreenFlash('#4CAF5066'); setTimeout(() => setScreenFlash(null), 300);
        if (attack.selfSleep) { attackerStatusArr[attackerActive] = 'sleep'; setAttackerStatus(attackerStatusArr); sleepTurns[attackerActive] = 0; setSleepTurns(sleepTurns); setTimeout(() => addFloatingText('💤', '#3B9AE1', false, attackerSide), 400); }
        setTimeout(() => { setTurn(turn === 1 ? 2 : 1); setMessage(`${turn === 1 ? trainer2.name : trainer1.name}'s turn!`); setAnimating(false); }, 1000);
        return;
      }
      
      // Stat boosts
      if (attack.boostAtk || attack.boostDef || attack.boostSpd) {
        const newBoosts = {...attackerBoostsArr[attackerActive]};
        let txt = '';
        const boostAmount = attack.boostAtk2 ? 2 : 1;
        if (attack.boostAtk) { newBoosts.atk = Math.min(6, newBoosts.atk + boostAmount); txt += 'ATK '; }
        if (attack.boostDef) { newBoosts.def = Math.min(6, newBoosts.def + 1); txt += 'DEF '; }
        if (attack.boostSpd) { newBoosts.spd = Math.min(6, newBoosts.spd + 1); txt += 'SPD '; }
        attackerBoostsArr[attackerActive] = newBoosts; setAttackerBoosts(attackerBoostsArr);
        playSound('boost');
        addFloatingText(`📈 ${txt}UP!`, '#FFD700', true, attackerSide);
        setScreenFlash('#FFD70044'); setTimeout(() => setScreenFlash(null), 300);
        setTimeout(() => { setTurn(turn === 1 ? 2 : 1); setMessage(`${turn === 1 ? trainer2.name : trainer1.name}'s turn!`); setAnimating(false); }, 1000);
        return;
      }

      // Accuracy check
      if (Math.random() * 100 > attack.accuracy) {
        playSound('miss');
        addFloatingText('MISS!', '#888', true, defenderSide);
        setTimeout(() => { setTurn(turn === 1 ? 2 : 1); setMessage(`${turn === 1 ? trainer2.name : trainer1.name}'s turn!`); setAnimating(false); }, 1200);
        return;
      }

      // Status moves
      if (attack.power === 0 && attack.effect) {
        if (!defenderStatusArr[defenderActive]) {
          defenderStatusArr[defenderActive] = attack.effect; setDefenderStatus(defenderStatusArr);
          addFloatingText(`${STATUS_DATA[attack.effect].name}!`, STATUS_DATA[attack.effect].color, true, defenderSide);
          setScreenFlash(STATUS_DATA[attack.effect].color + '66'); setTimeout(() => setScreenFlash(null), 300);
        } else { addFloatingText('FAILED!', '#888', false, defenderSide); }
        setTimeout(() => { setTurn(turn === 1 ? 2 : 1); setMessage(`${turn === 1 ? trainer2.name : trainer1.name}'s turn!`); setAnimating(false); }, 1200);
        return;
      }

      // Damage calculation
      const effectiveness = getEffectiveness(attack.type, defender.type);
      const atkStat = attacker.atk * (1 + attackerBoosts.atk * 0.5);
      const defStat = defender.def * (1 + defenderBoosts.def * 0.5);
      const critChance = attack.critBoost ? 0.25 : 0.0625;
      const isCrit = Math.random() < critChance;
      const critMult = isCrit ? 1.5 : 1;
      const randomMult = 0.85 + Math.random() * 0.15;
      let damage = Math.floor(((22 * attack.power * (atkStat / defStat)) / 50 + 2) * effectiveness * critMult * randomMult);
      if (attackerStatus === 'burn') damage = Math.floor(damage * 0.5);
      damage = Math.max(1, damage);
      if (effectiveness === 0) damage = 0;
      
      // Recoil
      if (attack.recoil) {
        const recoilDmg = Math.floor(damage * attack.recoil / 100);
        attackerHP[attackerActive] = Math.max(0, attackerHP[attackerActive] - recoilDmg);
        setAttackerHP(attackerHP);
        setTimeout(() => addFloatingText(`-${recoilDmg}`, '#FF8800', false, attackerSide), 500);
      }

      // Play defender hurt cry!
      if (damage > 0) {
        setTimeout(() => playPokemonCry(defender.cry), 150);
      }

      setFlashTarget(isP1 ? 2 : 1);
      setTimeout(() => { setFlashTarget(null); setShakeTarget(isP1 ? 2 : 1); setTimeout(() => setShakeTarget(null), 400); }, 100);

      if (effectiveness > 1) {
        playSound('superEffective');
        setScreenFlash('#FFD70088');
        setTimeout(() => { addFloatingText('SUPER EFFECTIVE!', '#FFD700', true, defenderSide); setTimeout(() => addFloatingText(`-${damage}`, '#FF4444', true, defenderSide), 250); }, 150);
      } else if (effectiveness < 1 && effectiveness > 0) {
        setTimeout(() => { addFloatingText('Not effective...', '#888', false, defenderSide); setTimeout(() => addFloatingText(`-${damage}`, '#FFAA44', false, defenderSide), 250); }, 150);
      } else if (effectiveness === 0) {
        playSound('miss');
        addFloatingText('NO EFFECT!', '#666', true, defenderSide);
        setTimeout(() => { setTurn(turn === 1 ? 2 : 1); setMessage(`${turn === 1 ? trainer2.name : trainer1.name}'s turn!`); setAnimating(false); }, 1200);
        return;
      } else {
        setTimeout(() => addFloatingText(`-${damage}`, '#FF4444', true, defenderSide), 150);
      }
      
      if (isCrit) { playSound('crit'); setTimeout(() => addFloatingText('CRITICAL!', '#FF6B6B', true, defenderSide), 50); setScreenFlash('#FF444488'); }
      setTimeout(() => setScreenFlash(null), 300);

      defenderHP[defenderActive] = Math.max(0, defenderHP[defenderActive] - damage);
      setDefenderHP(defenderHP);

      if (attack.selfDestruct) { attackerHP[attackerActive] = 0; setAttackerHP(attackerHP); addFloatingText('💥 BOOM!', '#FF6B35', true, attackerSide); }
      if (attack.drainHP && damage > 0) { const drain = Math.floor(damage / 2); attackerHP[attackerActive] = Math.min(attacker.hp, attackerHP[attackerActive] + drain); setAttackerHP(attackerHP); setTimeout(() => addFloatingText(`+${drain}`, '#4CAF50', false, attackerSide), 600); }
      if (attack.effect && attack.effectChance && Math.random() * 100 < attack.effectChance && !defenderStatusArr[defenderActive]) { defenderStatusArr[defenderActive] = attack.effect; setDefenderStatus(defenderStatusArr); setTimeout(() => addFloatingText(`${STATUS_DATA[attack.effect].icon}`, STATUS_DATA[attack.effect].color, false, defenderSide), 700); }

      setTimeout(() => {
        if (attack.selfDestruct && attackerHP[attackerActive] <= 0) {
          playSound('faint'); setFaintingPokemon(isP1 ? 1 : 2);
          setTimeout(() => {
            setFaintingPokemon(null);
            const nextAlive = attackerHP.findIndex((hp) => hp > 0);
            if (nextAlive === -1 && defenderHP[defenderActive] <= 0) { setShowConfetti(true); setPhase('gameover'); setWinner(0); return; }
            else if (nextAlive === -1) { playSound('victory'); setShowConfetti(true); setWinner(isP1 ? 2 : 1); setPhase('gameover'); return; }
          }, 800);
        }
        
        if (defenderHP[defenderActive] <= 0) {
          playSound('faint'); setFaintingPokemon(isP1 ? 2 : 1);
          addFloatingText('K.O.!', '#FF4444', true, defenderSide);
          setScreenFlash('#00000088'); setTimeout(() => setScreenFlash(null), 400);
          setTimeout(() => {
            setFaintingPokemon(null);
            const nextAlive = defenderHP.findIndex((hp) => hp > 0);
            if (nextAlive === -1) { playSound('victory'); setShowConfetti(true); setWinner(turn); setPhase('gameover'); return; }
            else { setDefenderActive(nextAlive); setMessage(`Go, ${defenderTeam[nextAlive].name}!`); }
            finishTurn();
          }, 1000);
          return;
        }
        
        if (attack.recoil && attackerHP[attackerActive] <= 0) {
          playSound('faint'); setFaintingPokemon(isP1 ? 1 : 2);
          setTimeout(() => {
            setFaintingPokemon(null);
            const nextAlive = attackerHP.findIndex((hp) => hp > 0);
            if (nextAlive === -1) { playSound('victory'); setShowConfetti(true); setWinner(isP1 ? 2 : 1); setPhase('gameover'); return; }
            else { if (isP1) setPlayer1Active(nextAlive); else setPlayer2Active(nextAlive); setMessage(`Go, ${(isP1 ? player1Team : player2Team)[nextAlive].name}!`); }
            finishTurn();
          }, 800);
          return;
        }
        
        finishTurn();
      }, 700);
    }, 500);

    function finishTurn() {
      const curHP = isP1 ? [...player2HP] : [...player1HP];
      const curStatus = isP1 ? player2Status[player2Active] : player1Status[player1Active];
      const curActive = isP1 ? player2Active : player1Active;
      const curPokemon = isP1 ? player2Team[player2Active] : player1Team[player1Active];
      const setCurHP = isP1 ? setPlayer2HP : setPlayer1HP;
      
      if ((curStatus === 'burn' || curStatus === 'poison') && curHP[curActive] > 0) {
        const statusDmg = Math.floor(curPokemon.hp / 8);
        curHP[curActive] = Math.max(0, curHP[curActive] - statusDmg);
        setCurHP(curHP);
        setTimeout(() => {
          addFloatingText(`-${statusDmg}`, curStatus === 'burn' ? '#FF6B35' : '#A040A0', false, defenderSide);
          if (curHP[curActive] <= 0) {
            playSound('faint'); setFaintingPokemon(isP1 ? 2 : 1); addFloatingText('K.O.!', '#FF4444', true, defenderSide);
            setTimeout(() => {
              setFaintingPokemon(null);
              const nextAlive = curHP.findIndex((hp) => hp > 0);
              if (nextAlive === -1) { playSound('victory'); setShowConfetti(true); setWinner(turn); setPhase('gameover'); return; }
              else { if (isP1) setPlayer2Active(nextAlive); else setPlayer1Active(nextAlive); }
              switchTurn();
            }, 800);
            return;
          }
          switchTurn();
        }, 400);
        return;
      }
      switchTurn();
    }
    
    function switchTurn() { setTimeout(() => { setTurn(turn === 1 ? 2 : 1); setMessage(`${turn === 1 ? trainer2.name : trainer1.name}'s turn!`); setAnimating(false); }, 500); }
  };

  if (showVS) return <VSScreen team1={player1Team} team2={player2Team} trainer1={trainer1} trainer2={trainer2} onComplete={onVSComplete} />;

  // Trainer selection screens
  if (phase === 'trainer1' || phase === 'trainer2') {
    const currentPlayer = phase === 'trainer1' ? 1 : 2;
    const selectedTrainer = phase === 'trainer1' ? trainer1 : trainer2;
    const setTrainer = phase === 'trainer1' ? setTrainer1 : setTrainer2;
    const otherTrainer = phase === 'trainer1' ? null : trainer1;
    
    return (
      <div style={{ minHeight: '100vh', position: 'relative', fontFamily: "'Segoe UI', sans-serif", display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
        <AnimatedBackground />
        <div style={{ position: 'relative', zIndex: 1, padding: '10px', textAlign: 'center' }}>
          <h2 style={{ color: currentPlayer === 1 ? '#FF6B6B' : '#4ECDC4', fontSize: '20px', margin: '0 0 10px 0' }}>Player {currentPlayer}: Choose Your Trainer!</h2>
          
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: '6px', maxWidth: '600px', margin: '0 auto' }}>
            {TRAINERS.map(trainer => {
              const isSelected = selectedTrainer?.id === trainer.id;
              const isDisabled = otherTrainer?.id === trainer.id;
              return (
                <div key={trainer.id} onClick={() => !isDisabled && setTrainer(trainer)} style={{ 
                  padding: '8px 4px', borderRadius: '10px',
                  background: isSelected ? `linear-gradient(135deg, ${trainer.color} 0%, ${trainer.color}88 100%)` : 'linear-gradient(145deg, #2d2d44, #1a1a2e)',
                  border: isSelected ? '2px solid #FFD700' : '1px solid #444',
                  cursor: isDisabled ? 'not-allowed' : 'pointer',
                  opacity: isDisabled ? 0.3 : 1,
                  transform: isSelected ? 'scale(1.05)' : 'scale(1)',
                  boxShadow: isSelected ? `0 0 12px ${trainer.color}` : 'none',
                  transition: 'all 0.2s'
                }}>
                  <img src={trainer.img} alt={trainer.name} style={{ width: '48px', height: '48px', imageRendering: 'pixelated' }} />
                  <div style={{ color: 'white', fontWeight: 'bold', fontSize: '11px' }}>{trainer.name}</div>
                </div>
              );
            })}
          </div>
          
          {selectedTrainer && (
            <button onClick={() => { playSound('select'); setPhase(phase === 'trainer1' ? 'trainer2' : 'select1'); }} style={{ 
              marginTop: '10px', padding: '10px 30px', fontSize: '16px', fontWeight: 'bold',
              background: 'linear-gradient(180deg, #4CAF50 0%, #2E7D32 100%)', color: 'white',
              border: '2px solid #81C784', borderRadius: '10px', cursor: 'pointer'
            }}>
              {phase === 'trainer1' ? `I'm ${selectedTrainer.name}! →` : `Let's GO! →`}
            </button>
          )}
        </div>
      </div>
    );
  }

  if (phase === 'select1' || phase === 'select2') {
    const currentPlayer = phase === 'select1' ? 1 : 2;
    const currentTrainer = phase === 'select1' ? trainer1 : trainer2;
    const currentTeam = phase === 'select1' ? player1Team : player2Team;
    const otherTeam = phase === 'select1' ? [] : player1Team;
    return (
      <div style={{ minHeight: '100vh', position: 'relative', fontFamily: "'Segoe UI', sans-serif", display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
        <AnimatedBackground />
        <div style={{ position: 'relative', zIndex: 1, padding: '8px' }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '12px', marginBottom: '6px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '6px', background: `${currentTrainer.color}33`, padding: '5px 10px', borderRadius: '8px', border: `2px solid ${currentTrainer.color}` }}>
              <img src={currentTrainer.img} alt={currentTrainer.name} style={{ width: '22px', height: '22px', imageRendering: 'pixelated' }} />
              <span style={{ color: currentTrainer.color, fontSize: '14px', fontWeight: 'bold' }}>{currentTrainer.name}</span>
              <div style={{ display: 'flex', gap: '3px', marginLeft: '6px' }}>
                {[0, 1, 2].map(i => {
                  const p = currentTeam[i];
                  const typeData = p ? TYPE_DATA[p.type] : null;
                  return <div key={i} style={{ width: '36px', height: '36px', borderRadius: '50%', border: `2px dashed ${p ? typeData.color : '#666'}`, display: 'flex', alignItems: 'center', justifyContent: 'center', background: p ? `${typeData.color}33` : 'transparent', overflow: 'hidden' }}>{p ? <img src={p.img} alt={p.name} style={{ width: '32px', height: '32px' }} /> : '?'}</div>;
                })}
              </div>
            </div>
            {currentTeam.length === 3 && (
              <button onClick={() => { playSound('select'); phase === 'select1' ? setPhase('select2') : startBattle(); }} style={{ padding: '8px 20px', fontSize: '14px', fontWeight: 'bold', background: 'linear-gradient(180deg, #4CAF50 0%, #2E7D32 100%)', color: 'white', border: '2px solid #81C784', borderRadius: '8px', cursor: 'pointer' }}>
                {phase === 'select1' ? <><img src={trainer2.img} alt={trainer2.name} style={{ width: '16px', height: '16px', verticalAlign: 'middle', imageRendering: 'pixelated' }} /> Next →</> : "⚔️ BATTLE!"}
              </button>
            )}
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: '3px', maxWidth: '750px', margin: '0 auto' }}>
            {POKEMON.map(pokemon => <PokemonCard key={pokemon.id} pokemon={pokemon} selected={currentTeam.find(p => p.id === pokemon.id)} disabled={otherTeam.find(p => p.id === pokemon.id)} onClick={() => selectPokemon(pokemon, currentPlayer)} />)}
          </div>
        </div>
      </div>
    );
  }

  if (phase === 'battle') {
    const p1Pokemon = player1Team[player1Active];
    const p2Pokemon = player2Team[player2Active];
    const currentPokemon = turn === 1 ? p1Pokemon : p2Pokemon;
    const currentTrainer = turn === 1 ? trainer1 : trainer2;
    const defenderType = turn === 1 ? p2Pokemon.type : p1Pokemon.type;
    return (
      <div style={{ minHeight: '100vh', position: 'relative', fontFamily: "'Segoe UI', sans-serif", display: 'flex', flexDirection: 'column' }}>
        <AnimatedBackground battle />
        {screenFlash && <ScreenFlash color={screenFlash} />}
        {attackAnim && <AttackAnimation type={attackAnim.type} side={attackAnim.side} />}
        {floatingTexts.map(ft => <FloatingText key={ft.id} text={ft.text} color={ft.color} large={ft.large} x={ft.x} />)}
        
        <div style={{ position: 'relative', zIndex: 1, textAlign: 'center', padding: '4px 10px', background: 'rgba(0,0,0,0.7)' }}>
          <div style={{ color: currentTrainer.color, fontSize: '16px', fontWeight: 'bold' }}>{message}</div>
        </div>
        
        <div style={{ position: 'relative', zIndex: 1, flex: 1, display: 'flex', alignItems: 'center', padding: '5px 10px' }}>
          {/* Left side - Player 1 */}
          <div style={{ flex: 1, textAlign: 'center' }}>
            <div style={{ fontSize: '12px', fontWeight: 'bold', color: turn === 1 ? '#FFD700' : '#888', marginBottom: '2px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '4px' }}>
              {turn === 1 && <span style={{ animation: 'pulse 1s infinite' }}>▶</span>}
              <img src={trainer1.img} alt={trainer1.name} style={{ width: '18px', height: '18px', imageRendering: 'pixelated' }} />
              <span style={{ color: trainer1.color }}>{trainer1.name}</span>
            </div>
            <TeamIndicator team={player1Team} hpArray={player1HP} activeIndex={player1Active} statuses={player1Status} canSwitch={turn === 1 && !animating} onSwitch={handleSwitch} />
            <BattlePokemon pokemon={p1Pokemon} hp={player1HP[player1Active]} maxHp={p1Pokemon.hp} status={player1Status[player1Active]} statBoosts={player1Boosts[player1Active]} shaking={shakeTarget === 1} flashing={flashTarget === 1} fainting={faintingPokemon === 1} isActive={turn === 1} />
          </div>
          
          {/* Center - VS and moves */}
          <div style={{ width: 'min(240px, 30vw)', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '4px' }}>
            <div style={{ fontSize: '20px' }}>⚔️</div>
            <div style={{ background: 'rgba(0,0,0,0.6)', borderRadius: '10px', padding: '6px', border: `2px solid ${currentTrainer.color}` }}>
              <div style={{ fontSize: '10px', color: '#FFD700', marginBottom: '3px', fontWeight: 'bold', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '3px' }}>
                <img src={currentPokemon.img} alt={currentPokemon.name} style={{ width: '28px', height: '28px' }} />
                {currentPokemon.name}
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '2px' }}>
                {currentPokemon.attacks.map((attack, i) => <AttackButton key={i} attack={attack} disabled={animating} onClick={() => doAttack(attack)} defenderType={defenderType} slotIndex={i} />)}
              </div>
            </div>
          </div>
          
          {/* Right side - Player 2 */}
          <div style={{ flex: 1, textAlign: 'center' }}>
            <div style={{ fontSize: '12px', fontWeight: 'bold', color: turn === 2 ? '#FFD700' : '#888', marginBottom: '2px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '4px' }}>
              <span style={{ color: trainer2.color }}>{trainer2.name}</span>
              <img src={trainer2.img} alt={trainer2.name} style={{ width: '18px', height: '18px', imageRendering: 'pixelated' }} />
              {turn === 2 && <span style={{ animation: 'pulse 1s infinite' }}>◀</span>}
            </div>
            <TeamIndicator team={player2Team} hpArray={player2HP} activeIndex={player2Active} statuses={player2Status} canSwitch={turn === 2 && !animating} onSwitch={handleSwitch} />
            <BattlePokemon pokemon={p2Pokemon} hp={player2HP[player2Active]} maxHp={p2Pokemon.hp} status={player2Status[player2Active]} statBoosts={player2Boosts[player2Active]} shaking={shakeTarget === 2} flashing={flashTarget === 2} fainting={faintingPokemon === 2} isActive={turn === 2} />
          </div>
        </div>
        <style>{`@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.3; } }`}</style>
      </div>
    );
  }

  if (phase === 'gameover') {
    const winnerTrainer = winner === 1 ? trainer1 : winner === 2 ? trainer2 : null;
    const loserTrainer = winner === 1 ? trainer2 : winner === 2 ? trainer1 : null;
    const winningTeam = winner === 1 ? player1Team : winner === 2 ? player2Team : [];
    return (
      <div style={{ minHeight: '100vh', position: 'relative', fontFamily: "'Segoe UI', sans-serif", display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <AnimatedBackground />
        {showConfetti && <Confetti />}
        <style>{`
          @keyframes bounce { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
          @keyframes glow { 0%, 100% { text-shadow: 0 0 15px #FFD700; } 50% { text-shadow: 0 0 30px #FFD700, 0 0 50px #FFD700; } }
          @keyframes winnerPulse { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.05); } }
        `}</style>
        <div style={{ position: 'relative', zIndex: 1, textAlign: 'center', display: 'flex', alignItems: 'center', gap: '30px' }}>
          <div style={{ fontSize: '70px', animation: 'bounce 1s infinite' }}>🏆</div>
          
          {winnerTrainer ? (
            <div style={{ textAlign: 'center' }}>
              <img src={winnerTrainer.img} alt={winnerTrainer.name} style={{ width: '70px', height: '70px', marginBottom: '5px', animation: 'winnerPulse 1.5s infinite', filter: `drop-shadow(0 0 15px ${winnerTrainer.color})`, imageRendering: 'pixelated' }} />
              <h1 style={{ color: winnerTrainer.color, fontSize: '36px', margin: '0 0 5px 0', animation: 'glow 2s infinite' }}>
                {winnerTrainer.name} WINS!
              </h1>
              <div style={{ color: '#aaa', fontSize: '14px' }}>
                defeated {loserTrainer && <img src={loserTrainer.img} alt={loserTrainer.name} style={{ width: '16px', height: '16px', verticalAlign: 'middle', imageRendering: 'pixelated' }} />} {loserTrainer?.name}
              </div>
            </div>
          ) : (
            <div style={{ textAlign: 'center' }}>
              <h1 style={{ color: '#FFD700', fontSize: '36px', margin: '0 0 10px 0', animation: 'glow 2s infinite' }}>IT'S A DRAW!</h1>
              <div style={{ display: 'flex', gap: '15px', justifyContent: 'center', alignItems: 'center' }}>
                {trainer1 && <img src={trainer1.img} alt={trainer1.name} style={{ width: '50px', height: '50px', imageRendering: 'pixelated' }} />}
                <div style={{ fontSize: '24px', color: '#888' }}>🤝</div>
                {trainer2 && <img src={trainer2.img} alt={trainer2.name} style={{ width: '50px', height: '50px', imageRendering: 'pixelated' }} />}
              </div>
            </div>
          )}
          
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '12px' }}>
            {winnerTrainer && (
              <div style={{ display: 'flex', gap: '8px' }}>
                {winningTeam.map((p, i) => (
                  <div key={i} style={{ 
                    animation: `bounce 1s infinite ${i * 0.15}s`, 
                    filter: `drop-shadow(0 0 10px ${winnerTrainer.color})`,
                    background: 'rgba(0,0,0,0.3)',
                    borderRadius: '50%',
                    width: '60px',
                    height: '60px',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    overflow: 'hidden'
                  }}><img src={p.img} alt={p.name} style={{ width: '52px', height: '52px' }} /></div>
                ))}
              </div>
            )}
            <button onClick={resetGame} style={{ 
              padding: '12px 30px', fontSize: '18px', fontWeight: 'bold',
              background: 'linear-gradient(180deg, #4CAF50 0%, #2E7D32 100%)', color: 'white',
              border: '2px solid #81C784', borderRadius: '12px', cursor: 'pointer'
            }}>
              🎮 PLAY AGAIN 🎮
            </button>
          </div>
        </div>
      </div>
    );
  }
}
